def two_sum(nums: list[int], target: int) -> list[int]:
    """Return the indices of the unique pair whose values sum to target."""
    seen: dict[int, int] = {}
    for index, value in enumerate(nums):
        complement = target - value
        # Check before inserting so an element is never paired with itself.
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index
    raise ValueError("no valid pair")

from collections import Counter, defaultdict


def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words by their character multiset."""
    groups: defaultdict[frozenset, list[str]] = defaultdict(list)
    for word in words:
        # A frozen Counter key is O(len(word)) and works for any alphabet.
        groups[frozenset(Counter(word).items())].append(word)
    return list(groups.values())

def longest_consecutive(nums: list[int]) -> int:
    """Return the longest run of consecutive values in O(n) expected time."""
    values = set(nums)
    best = 0
    for value in values:
        # Only expand from run heads so every run is walked once.
        if value - 1 in values:
            continue
        length = 1
        while value + length in values:
            length += 1
        best = max(best, length)
    return best

def max_container_area(heights: list[int]) -> int:
    """Return the best container area using converging pointers."""
    left, right = 0, len(heights) - 1
    best = 0
    while left < right:
        left_height, right_height = heights[left], heights[right]
        best = max(best, (right - left) * min(left_height, right_height))
        # The shorter side cannot do better with any narrower partner, so drop it.
        if left_height < right_height:
            left += 1
        else:
            right -= 1
    return best

def three_sum(nums: list[int]) -> list[list[int]]:
    """Return unique zero-sum triplets using sort + two pointers."""
    values = sorted(nums)
    result: list[list[int]] = []
    for i in range(len(values) - 2):
        if i > 0 and values[i] == values[i - 1]:
            continue
        if values[i] > 0:
            break
        left, right = i + 1, len(values) - 1
        while left < right:
            total = values[i] + values[left] + values[right]
            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                result.append([values[i], values[left], values[right]])
                left += 1
                right -= 1
                # Skip equal values so each triplet is emitted once.
                while left < right and values[left] == values[left - 1]:
                    left += 1
    return result

def longest_unique_substring(text: str) -> int:
    """Return the longest repeat-free window length in one pass."""
    last_seen: dict[str, int] = {}
    left = 0
    best = 0
    for right, char in enumerate(text):
        # Only jump forward: an older occurrence may sit left of the window already.
        if last_seen.get(char, -1) >= left:
            left = last_seen[char] + 1
        last_seen[char] = right
        best = max(best, right - left + 1)
    return best

def _lower_bound(nums: list[int], target: int) -> int:
    """Return the first index whose value is >= target (half-open search on [lo, hi))."""
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def search_range(nums: list[int], target: int) -> list[int]:
    """Return [first, last] index of target in sorted nums, or [-1, -1]."""
    first = _lower_bound(nums, target)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    # The last match sits just before the first value > target.
    return [first, _lower_bound(nums, target + 1) - 1]

def split_array(nums: list[int], k: int) -> int:
    """Return the minimized largest part sum via binary search on the answer."""
    if k < 1 or k > len(nums):
        raise ValueError(f"cannot split {len(nums)} values into {k} nonempty parts")

    def parts_needed(cap: int) -> int:
        # Greedy packing gives the fewest parts with every part sum <= cap.
        parts, current = 1, 0
        for value in nums:
            if current + value > cap:
                parts += 1
                current = 0
            current += value
        return parts

    # Feasibility (parts_needed(cap) <= k) is monotone in cap; find the smallest feasible cap.
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if parts_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def is_valid_parentheses(text: str) -> bool:
    """Return whether brackets in text are properly matched and nested."""
    closer_to_opener = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []
    for char in text:
        if char in closer_to_opener:
            if not stack or stack.pop() != closer_to_opener[char]:
                return False
        else:
            stack.append(char)
    return not stack

def daily_temperatures(temperatures: list[int]) -> list[int]:
    """Return days until a warmer temperature using a monotonic stack of indices."""
    answer = [0] * len(temperatures)
    stack: list[int] = []  # indices of days still waiting, temperatures non-increasing
    for day, temp in enumerate(temperatures):
        while stack and temperatures[stack[-1]] < temp:
            previous = stack.pop()
            answer[previous] = day - previous
        stack.append(day)
    return answer

def tree_depth_and_balanced(root) -> tuple[int, bool]:
    """Return (max depth, is height-balanced) in one post-order traversal."""

    def visit(node) -> tuple[int, bool]:
        if node is None:
            return 0, True
        left_depth, left_ok = visit(node.left)
        right_depth, right_ok = visit(node.right)
        balanced = left_ok and right_ok and abs(left_depth - right_depth) <= 1
        return 1 + max(left_depth, right_depth), balanced

    return visit(root)

from collections import deque


def level_order(root) -> list[list]:
    """Return values grouped by depth using BFS with explicit level boundaries."""
    if root is None:
        return []
    levels: list[list] = []
    queue = deque([root])
    while queue:
        level = []
        # The queue holds exactly one level at the top of each iteration.
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left is not None:
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
        levels.append(level)
    return levels

def num_islands(grid: list[list[str]]) -> int:
    """Count land components with iterative DFS and a visited set."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited: set[tuple[int, int]] = set()
    islands = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != "1" or (r, c) in visited:
                continue
            islands += 1
            visited.add((r, c))
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                for nr, nc in ((cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "1" and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
    return islands

from collections import deque


def grid_shortest_path(grid: list[list[int]]) -> int:
    """Return BFS distance in moves from top-left to bottom-right, or -1."""
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] or grid[rows - 1][cols - 1]:
        return -1
    seen = {(0, 0)}
    queue = deque([(0, 0, 0)])
    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == (rows - 1, cols - 1):
            return dist
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            # Mark on enqueue so each cell enters the queue at most once.
            if 0 <= nr < rows and 0 <= nc < cols and not grid[nr][nc] and (nr, nc) not in seen:
                seen.add((nr, nc))
                queue.append((nr, nc, dist + 1))
    return -1

def count_components(n: int, edges: list[list[int]]) -> int:
    """Count connected components with iterative DFS from every unvisited node."""
    adjacency: list[list[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)
    visited = [False] * n
    components = 0
    for start in range(n):
        if visited[start]:
            continue
        components += 1
        visited[start] = True
        stack = [start]
        while stack:
            node = stack.pop()
            for neighbor in adjacency[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
    return components

import heapq
from collections import Counter


def top_k_frequent(nums: list[int], k: int) -> list[int]:
    """Return k most frequent values using a size-k min-heap keyed by frequency."""
    heap: list[tuple[int, int]] = []
    for value, count in Counter(nums).items():
        if len(heap) < k:
            heapq.heappush(heap, (count, value))
        elif count > heap[0][0]:
            # The heap root is the least frequent of the current top k.
            heapq.heapreplace(heap, (count, value))
    return [value for _, value in heap]

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    """Merge overlapping closed intervals with sort + sweep."""
    merged: list[list[int]] = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            # Closed intervals: touching endpoints overlap; keep the farther end.
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

def max_non_adjacent_sum(nums: list[int]) -> int:
    """Return the best sum of non-adjacent elements (empty choice allowed)."""
    take, skip = 0, 0  # best sums ending with the current element taken / not taken
    for value in nums:
        take, skip = skip + value, max(take, skip)
    return max(take, skip)


def unique_paths(rows: int, cols: int) -> int:
    """Count right/down paths with a rolling row."""
    row = [1] * cols
    for _ in range(1, rows):
        for c in range(1, cols):
            row[c] += row[c - 1]
    return row[-1]


def unique_paths_with_obstacles(grid: list[list[int]]) -> int:
    """Count right/down paths avoiding obstacles with a rolling row."""
    cols = len(grid[0])
    row = [0] * cols
    row[0] = 1
    for cells in grid:
        for c in range(cols):
            if cells[c] == 1:
                row[c] = 0
            elif c > 0:
                row[c] += row[c - 1]
    return row[-1]


def min_path_sum(grid: list[list[int]]) -> int:
    """Return the minimum right/down path sum with a rolling row."""
    inf = float("inf")
    row = [inf] * len(grid[0])
    row[0] = 0
    for cells in grid:
        for c, value in enumerate(cells):
            best_prev = row[c] if c == 0 else min(row[c], row[c - 1])
            row[c] = best_prev + value
    return row[-1]


def edit_distance(source: str, target: str) -> int:
    """Return Levenshtein distance using two rolling rows."""
    previous = list(range(len(target) + 1))  # distance from "" to each target prefix
    for i, s_char in enumerate(source, start=1):
        current = [i] + [0] * len(target)
        for j, t_char in enumerate(target, start=1):
            if s_char == t_char:
                current[j] = previous[j - 1]
            else:
                current[j] = 1 + min(previous[j], current[j - 1], previous[j - 1])
        previous = current
    return previous[-1]

class _Node:
    __slots__ = ("children", "is_word")

    def __init__(self) -> None:
        self.children: dict[str, "_Node"] = {}
        self.is_word = False


class Trie:
    """Prefix tree with exact lookup, prefix lookup, and ordered completions."""

    def __init__(self) -> None:
        self.root = _Node()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            node = node.children.setdefault(char, _Node())
        node.is_word = True

    def _find(self, prefix: str) -> "_Node | None":
        node = self.root
        for char in prefix:
            node = node.children.get(char)
            if node is None:
                return None
        return node

    def contains(self, word: str) -> bool:
        node = self._find(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        node = self._find(prefix)
        # Nodes are only created by insert, so any reachable node has a word beneath it.
        return node is not None and (node.is_word or bool(node.children))

    def complete(self, prefix: str, k: int) -> list[str]:
        start = self._find(prefix)
        results: list[str] = []
        if start is None or k <= 0:
            return results
        # Pre-order DFS with sorted children yields words in lexicographic order,
        # so enumeration can stop as soon as k words are found.
        stack = [(start, prefix)]
        while stack and len(results) < k:
            node, text = stack.pop()
            if node.is_word:
                results.append(text)
            for char in sorted(node.children, reverse=True):
                stack.append((node.children[char], text + char))
        return results

class UnionFind:
    """Disjoint-set union with path compression and union by size."""

    def __init__(self, n: int) -> None:
        self.parent = list(range(n))
        self.size = [1] * n
        self.count = n

    def find(self, x: int) -> int:
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        # Second pass: point every node on the path directly at the root.
        while self.parent[x] != root:
            self.parent[x], x = root, self.parent[x]
        return root

    def union(self, a: int, b: int) -> bool:
        root_a, root_b = self.find(a), self.find(b)
        if root_a == root_b:
            return False
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a  # smaller tree under larger keeps depth O(log n)
        self.size[root_a] += self.size[root_b]
        self.count -= 1
        return True

    def connected(self, a: int, b: int) -> bool:
        return self.find(a) == self.find(b)

import heapq
from itertools import count
from typing import Hashable

Graph = dict[Hashable, list[tuple[Hashable, float]]]


def dijkstra(graph: Graph, source: Hashable, target: Hashable) -> tuple[dict[Hashable, float], list[Hashable]]:
    """Return shortest distances from source and one shortest path to target."""
    if any(weight < 0 for edges in graph.values() for _, weight in edges):
        raise ValueError("Dijkstra requires nonnegative edge weights")

    dist: dict[Hashable, float] = {source: 0}
    previous: dict[Hashable, Hashable] = {}
    settled: set[Hashable] = set()
    tie = count()  # breaks distance ties without comparing node objects
    heap = [(0, next(tie), source)]
    while heap:
        d, _, node = heapq.heappop(heap)
        if node in settled:
            continue  # stale entry: a shorter distance was already settled
        settled.add(node)
        for neighbor, weight in graph.get(node, []):
            candidate = d + weight
            if candidate < dist.get(neighbor, float("inf")):
                dist[neighbor] = candidate
                previous[neighbor] = node
                heapq.heappush(heap, (candidate, next(tie), neighbor))

    if target not in dist:
        return dist, []
    path = [target]
    while path[-1] != source:
        path.append(previous[path[-1]])
    return dist, path[::-1]

import time
from typing import Callable

_EPSILON = 1e-9


class TokenBucket:
    """Lazily refilled token bucket with an injectable clock."""

    def __init__(self, capacity: float, refill_rate: float, clock: Callable[[], float] = time.monotonic) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_rate < 0:
            raise ValueError("refill_rate must be nonnegative")
        self.capacity = capacity
        self.refill_rate = refill_rate
        self._clock = clock
        self._tokens = float(capacity)
        self._last = clock()

    def _refill(self) -> None:
        now = self._clock()
        # Ignore backwards clock movement; only forward progress earns tokens.
        if now > self._last:
            self._tokens = min(self.capacity, self._tokens + (now - self._last) * self.refill_rate)
        self._last = max(self._last, now)

    def allow(self, cost: float = 1) -> bool:
        if cost <= 0 or cost > self.capacity:
            raise ValueError(f"cost must be in (0, {self.capacity}]")
        self._refill()
        if self._tokens + _EPSILON >= cost:
            self._tokens = max(0.0, self._tokens - cost)
            return True
        return False

import math

import numpy as np


def cosine_similarity(a: list[float], b: list[float]) -> float:
    """Direct arithmetic: dot / (|a| |b|), with a zero vector giving 0.0."""
    if len(a) != len(b):
        raise ValueError("vectors must have equal length")
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return float(dot / (norm_a * norm_b))


def _normalize_rows(x: np.ndarray) -> np.ndarray:
    norms = np.linalg.norm(x, axis=-1, keepdims=True)
    return np.divide(x, norms, out=np.zeros_like(x), where=norms > 0)


def _validate(queries: np.ndarray, candidates: np.ndarray, k: int) -> None:
    if candidates.ndim != 2 or queries.shape[-1] != candidates.shape[1]:
        raise ValueError("queries and candidates must share the last dimension d")
    if not 1 <= k <= len(candidates):
        raise ValueError("k must satisfy 1 <= k <= n")


def cosine_retrieve_batch(
    queries: np.ndarray, candidates: np.ndarray, k: int
) -> tuple[np.ndarray, np.ndarray]:
    """(m, k) top-k cosine indices/scores: normalize once, one matmul, stable sort."""
    queries = np.asarray(queries, dtype=float)
    candidates = np.asarray(candidates, dtype=float)
    if queries.ndim != 2:
        raise ValueError("queries must be (m, d)")
    _validate(queries, candidates, k)
    scores = _normalize_rows(queries) @ _normalize_rows(candidates).T  # (m, n)
    order = np.argsort(-scores, axis=1, kind="stable")[:, :k]  # stable: ties by index
    return order, np.take_along_axis(scores, order, axis=1)


def cosine_retrieve(query: np.ndarray, candidates: np.ndarray, k: int) -> tuple[np.ndarray, np.ndarray]:
    """Single (d,) query: the batch path with m = 1, returned as 1-D arrays."""
    query = np.asarray(query, dtype=float)
    if query.ndim != 1:
        raise ValueError("query must be (d,)")
    indices, scores = cosine_retrieve_batch(query[None, :], candidates, k)
    return indices[0], scores[0]

import hashlib

import numpy as np

N_BUCKETS = 10_000


def hash_bucket(group: object, salt: str = "", n_buckets: int = N_BUCKETS) -> int:
    """Process-independent bucket: sha256 of "salt:group" modulo n_buckets."""
    digest = hashlib.sha256(f"{salt}:{group}".encode("utf-8")).hexdigest()
    return int(digest, 16) % n_buckets


def _check_fraction(test_fraction: float) -> None:
    if not 0 < test_fraction < 1:
        raise ValueError("test_fraction must be in (0, 1)")


def group_hash_split(groups: list[object], test_fraction: float, salt: str = "") -> np.ndarray:
    """Test iff the group's stable bucket falls below the threshold; groups never split."""
    _check_fraction(test_fraction)
    threshold = test_fraction * N_BUCKETS
    # Hash each distinct group once, then broadcast back to rows.
    bucket = {g: hash_bucket(g, salt) for g in set(groups)}
    return np.array([bucket[g] < threshold for g in groups], dtype=bool)


def grouped_split(groups: list[object], test_fraction: float, seed: int) -> np.ndarray:
    """Seeded shuffle of the sorted distinct groups; the first n_test groups go to test."""
    _check_fraction(test_fraction)
    distinct = sorted(set(groups))  # sorting makes the result independent of row order
    g = len(distinct)
    if g < 2:
        raise ValueError("need at least two groups")
    n_test = min(g - 1, max(1, round(test_fraction * g)))
    order = np.random.default_rng(seed).permutation(g)
    test_groups = {distinct[i] for i in order[:n_test]}
    return np.array([x in test_groups for x in groups], dtype=bool)


def temporal_split(times: np.ndarray, cutoff: object, embargo: object = 0) -> tuple[np.ndarray, np.ndarray]:
    """train: time < cutoff - embargo; test: time >= cutoff; the gap in between is dropped."""
    times = np.asarray(times)
    zero = embargo * 0  # a zero of the same type: comparing timedelta64 with a bare 0 is deprecated
    if embargo < zero:
        raise ValueError("embargo must be non-negative")
    return times < cutoff - embargo, times >= cutoff


def check_leakage(
    train_mask: np.ndarray,
    test_mask: np.ndarray,
    groups: list[object] | None = None,
    times: np.ndarray | None = None,
    embargo: object = 0,
) -> list[str]:
    """Sorted names of violated leakage invariants."""
    train = np.asarray(train_mask, dtype=bool)
    test = np.asarray(test_mask, dtype=bool)
    if not train.any() or not test.any():
        return []
    violations = []
    if (train & test).any():
        violations.append("row_overlap")
    if groups is not None:
        groups = np.asarray(groups, dtype=object)
        if set(groups[train]) & set(groups[test]):
            violations.append("group_overlap")
    if times is not None:
        times = np.asarray(times)
        latest_train, earliest_test = times[train].max(), times[test].min()
        if latest_train >= earliest_test:
            violations.append("temporal_order")
        elif embargo > embargo * 0 and earliest_test - latest_train <= embargo:
            violations.append("embargo")
    return sorted(violations)

import numpy as np

REDUCTIONS = ("none", "mean", "sum")


def _reduce(losses: np.ndarray, reduction: str) -> np.ndarray | float:
    if reduction == "none":
        return losses
    return float(losses.mean() if reduction == "mean" else losses.sum())


def logsumexp(x: np.ndarray, axis: int = -1) -> np.ndarray:
    """max + log(sum(exp(x - max))): every exponent is <= 0, so nothing overflows."""
    x = np.asarray(x, dtype=float)
    m = np.max(x, axis=axis, keepdims=True)
    out = m + np.log(np.sum(np.exp(x - m), axis=axis, keepdims=True))
    return np.squeeze(out, axis=axis)


def softmax(x: np.ndarray, axis: int = -1) -> np.ndarray:
    """exp(x - logsumexp(x)) along axis."""
    x = np.asarray(x, dtype=float)
    return np.exp(x - np.expand_dims(logsumexp(x, axis=axis), axis))


def cross_entropy(logits: np.ndarray, targets: np.ndarray, reduction: str = "mean") -> np.ndarray | float:
    """Fused log-softmax + NLL: logsumexp(z_i) - z_i[y_i]."""
    logits = np.asarray(logits, dtype=float)
    targets = np.asarray(targets)
    if logits.ndim != 2 or targets.shape != (logits.shape[0],):
        raise ValueError("expected logits (B, C) and targets (B,)")
    if np.any((targets < 0) | (targets >= logits.shape[1])):
        raise ValueError("targets must lie in [0, C)")
    if reduction not in REDUCTIONS:
        raise ValueError(f"reduction must be one of {REDUCTIONS}")
    # Row-wise gather: logits[i, targets[i]], not logits[:, targets].
    picked = logits[np.arange(len(targets)), targets]
    return _reduce(logsumexp(logits, axis=1) - picked, reduction)


def sigmoid(x: np.ndarray) -> np.ndarray:
    """Uses e = exp(-|x|) <= 1 in both branches, so neither np.where branch can overflow."""
    x = np.asarray(x, dtype=float)
    e = np.exp(-np.abs(x))
    return np.where(x >= 0, 1.0 / (1.0 + e), e / (1.0 + e))


def bce_with_logits(logits: np.ndarray, targets: np.ndarray, reduction: str = "mean") -> np.ndarray | float:
    """max(z, 0) - z*y + log1p(exp(-|z|)): the log-sigmoid identities, never log(sigmoid)."""
    z = np.asarray(logits, dtype=float)
    y = np.asarray(targets, dtype=float)
    if z.shape != y.shape:
        raise ValueError("logits and targets must have the same shape")
    if np.any((y < 0) | (y > 1)):
        raise ValueError("targets must lie in [0, 1]")
    if reduction not in REDUCTIONS:
        raise ValueError(f"reduction must be one of {REDUCTIONS}")
    losses = np.maximum(z, 0.0) - z * y + np.log1p(np.exp(-np.abs(z)))
    return _reduce(losses, reduction)


def naive_failure_examples() -> dict[str, np.ndarray]:
    """exp(1000) = inf, so inf / inf = NaN in both naive formulas."""
    return {"softmax": np.array([[1000.0, 999.0, 0.0]]), "sigmoid": np.array([-5.0, 1000.0])}

import numpy as np


def linear_regression_gd(
    x: np.ndarray, y: np.ndarray, learning_rate: float = 0.1, steps: int = 1000
) -> tuple[np.ndarray, float, list[float]]:
    """Full-batch GD on mean squared error / 2."""
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    n, d = x.shape
    w, b = np.zeros(d), 0.0
    history = []
    for _ in range(steps):
        r = x @ w + b - y
        w = w - learning_rate * (x.T @ r / n)
        b = b - learning_rate * r.mean()
        history.append(float(np.mean((x @ w + b - y) ** 2) / 2))
    return w, float(b), history


def _sigmoid(z: np.ndarray) -> np.ndarray:
    e = np.exp(-np.abs(z))  # <= 1, so neither branch overflows
    return np.where(z >= 0, 1.0 / (1.0 + e), e / (1.0 + e))


def _bce_from_logits(z: np.ndarray, y: np.ndarray) -> np.ndarray:
    # -[y log s(z) + (1 - y) log(1 - s(z))] = max(z, 0) - z y + log(1 + exp(-|z|))
    return np.maximum(z, 0.0) - z * y + np.log1p(np.exp(-np.abs(z)))


class LogisticRegression:
    """Binary logistic regression with unregularized intercept and optional mini-batches."""

    def __init__(
        self,
        learning_rate: float = 0.1,
        steps: int = 1000,
        l2: float = 0.0,
        batch_size: int | None = None,
        seed: int = 0,
    ) -> None:
        self.learning_rate = learning_rate
        self.steps = steps
        self.l2 = l2
        self.batch_size = batch_size
        self.seed = seed

    @staticmethod
    def _validate(x: np.ndarray, y: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        x = np.asarray(x, dtype=float)
        y = np.asarray(y)
        if x.ndim != 2 or y.shape != (x.shape[0],):
            raise ValueError("expected x (n, d) and y (n,)")
        if not np.all((y == 0) | (y == 1)):
            raise ValueError("labels must be 0/1")
        return x, y.astype(float)

    def loss(self, x: np.ndarray, y: np.ndarray) -> float:
        x, y = self._validate(x, y)
        z = x @ self.weights_ + self.bias_
        return float(_bce_from_logits(z, y).mean() + 0.5 * self.l2 * self.weights_ @ self.weights_)

    def gradient(self, x: np.ndarray, y: np.ndarray) -> tuple[np.ndarray, float]:
        x, y = self._validate(x, y)
        residual = _sigmoid(x @ self.weights_ + self.bias_) - y  # dBCE/dz
        grad_w = x.T @ residual / len(y) + self.l2 * self.weights_  # no penalty on the bias
        return grad_w, float(residual.mean())

    def fit(self, x: np.ndarray, y: np.ndarray) -> "LogisticRegression":
        x, y = self._validate(x, y)
        n, d = x.shape
        self.weights_, self.bias_ = np.zeros(d), 0.0
        self.loss_history_ = []
        rng = np.random.default_rng(self.seed)
        for _ in range(self.steps):
            if self.batch_size is None:
                batches = [np.arange(n)]
            else:
                order = rng.permutation(n)
                batches = [order[i:i + self.batch_size] for i in range(0, n, self.batch_size)]
            for idx in batches:
                grad_w, grad_b = self.gradient(x[idx], y[idx])
                self.weights_ = self.weights_ - self.learning_rate * grad_w
                self.bias_ = self.bias_ - self.learning_rate * grad_b
            self.loss_history_.append(self.loss(x, y))
        return self

    def predict_proba(self, x: np.ndarray) -> np.ndarray:
        return _sigmoid(np.asarray(x, dtype=float) @ self.weights_ + self.bias_)

    def predict(self, x: np.ndarray, threshold: float = 0.5) -> np.ndarray:
        return (self.predict_proba(x) >= threshold).astype(np.intp)

from collections import defaultdict

import numpy as np

# Below this acceptance rate, rejection sampling is replaced by sampling the explicit complement.
MIN_ACCEPTANCE = 0.1


def sample_negatives(
    interactions: list[tuple[int, int]],
    n_items: int,
    n_neg: int,
    seed: int,
    popularity: np.ndarray | None = None,
) -> np.ndarray:
    """Per-interaction negatives that exclude all of the user's positives (rejection sampling)."""
    if n_neg < 1:
        raise ValueError("n_neg must be >= 1")
    positives: dict[object, set[int]] = defaultdict(set)
    for user, item in interactions:
        if not 0 <= item < n_items:
            raise ValueError(f"item {item} outside [0, {n_items})")
        positives[user].add(int(item))

    rng = np.random.default_rng(seed)
    if popularity is None:
        probs, cdf = None, None
    else:
        weights = np.asarray(popularity, dtype=float)
        if weights.shape != (n_items,) or not np.all(np.isfinite(weights)) or np.any(weights < 0):
            raise ValueError("popularity must be (n_items,) finite and non-negative")
        if weights.sum() == 0:
            raise ValueError("popularity has no positive mass")
        probs = weights / weights.sum()
        cdf = np.cumsum(probs)  # O(n_items) setup, shared by all users
        cdf[-1] = 1.0

    out = np.empty((len(interactions), n_neg), dtype=np.int64)
    for row, (user, _) in enumerate(interactions):
        out[row] = _draw(positives[user], n_items, n_neg, rng, probs, cdf)
    return out


def _draw(
    excluded: set[int],
    n_items: int,
    n_neg: int,
    rng: np.random.Generator,
    probs: np.ndarray | None,
    cdf: np.ndarray | None,
) -> list[int]:
    """n_neg distinct items, each drawn proportionally to its weight among the remaining ones."""
    excluded_ids = np.fromiter(excluded, dtype=np.int64, count=len(excluded))
    if probs is None:
        eligible = n_items - len(excluded)
        acceptance = eligible / n_items
    else:
        eligible = int(np.count_nonzero(probs)) - int(np.count_nonzero(probs[excluded_ids]))
        acceptance = 1.0 - probs[excluded_ids].sum()
    if eligible < n_neg:
        raise ValueError("not enough eligible negatives for a user")

    if acceptance - n_neg / max(n_items, 1) < MIN_ACCEPTANCE:
        # Near-full-catalog user: sample the explicit complement (O(n_items) for this user only).
        allowed = np.setdiff1d(np.arange(n_items), excluded_ids)
        p = None if probs is None else probs[allowed] / probs[allowed].sum()
        if p is not None:
            allowed, p = allowed[p > 0], p[p > 0]
        return rng.choice(allowed, size=n_neg, replace=False, p=p).tolist()

    # Rejection: drawing from the full distribution and discarding excluded or already
    # chosen items is exactly sequential sampling without replacement from the rest.
    chosen: list[int] = []
    seen = set(excluded)
    while len(chosen) < n_neg:
        size = 2 * (n_neg - len(chosen)) + 4
        if probs is None:
            candidates = rng.integers(0, n_items, size=size)
        else:
            candidates = np.searchsorted(cdf, rng.random(size), side="right")
        for item in candidates.tolist():
            if item not in seen:
                seen.add(item)
                chosen.append(item)
                if len(chosen) == n_neg:
                    break
    return chosen

import numpy as np


def _class_probs(
    labels: np.ndarray | None, probs: np.ndarray | None, weights: np.ndarray | None
) -> np.ndarray:
    """Empirical (optionally weighted) class shares, or validated given probabilities."""
    if (labels is None) == (probs is None):
        raise ValueError("pass exactly one of labels or probs")
    if probs is not None:
        p = np.asarray(probs, dtype=float)
        if p.ndim != 1 or np.any(p < 0) or abs(p.sum() - 1.0) > 1e-9:
            raise ValueError("probs must be non-negative and sum to 1")
        return p
    labels = np.asarray(labels)
    if labels.ndim != 1 or labels.size == 0:
        raise ValueError("labels must be a non-empty 1-D array")
    w = np.ones(len(labels)) if weights is None else np.asarray(weights, dtype=float)
    if w.shape != labels.shape or np.any(w < 0) or w.sum() <= 0:
        raise ValueError("weights must be non-negative with a positive total")
    # np.unique handles strings and negative/large ints; bincount on raw labels would not.
    _, codes = np.unique(labels, return_inverse=True)
    mass = np.bincount(codes.ravel(), weights=w)
    return mass / mass.sum()


def entropy(
    labels: np.ndarray | None = None,
    probs: np.ndarray | None = None,
    weights: np.ndarray | None = None,
    base: float = 2.0,
) -> float:
    """Shannon entropy with 0 log 0 = 0."""
    p = _class_probs(labels, probs, weights)
    p = p[p > 0]  # drop zero classes before the log, so no log(0) is ever evaluated
    return float(max(0.0, -np.sum(p * np.log(p)) / np.log(base)))


def gini(
    labels: np.ndarray | None = None,
    probs: np.ndarray | None = None,
    weights: np.ndarray | None = None,
) -> float:
    """Gini impurity 1 - sum p^2."""
    p = _class_probs(labels, probs, weights)
    return float(max(0.0, 1.0 - np.sum(p * p)))


def _impurity(labels: np.ndarray, weights: np.ndarray | None, criterion: str, base: float) -> float:
    if criterion == "entropy":
        return entropy(labels=labels, weights=weights, base=base)
    if criterion == "gini":
        return gini(labels=labels, weights=weights)
    raise ValueError("criterion must be 'entropy' or 'gini'")


def weighted_child_impurity(
    labels: np.ndarray,
    left_mask: np.ndarray,
    criterion: str = "entropy",
    weights: np.ndarray | None = None,
    base: float = 2.0,
) -> float:
    """Children's impurities weighted by their share of the parent's sample weight."""
    labels = np.asarray(labels)
    mask = np.asarray(left_mask)
    if mask.dtype != np.bool_ or mask.shape != labels.shape:
        raise ValueError("left_mask must be a boolean array aligned with labels")
    w = np.ones(len(labels)) if weights is None else np.asarray(weights, dtype=float)
    w_left, w_right = w[mask].sum(), w[~mask].sum()
    if w_left <= 0 or w_right <= 0:
        raise ValueError("both children must be non-empty")
    child_w = None if weights is None else w
    left = _impurity(labels[mask], None if child_w is None else child_w[mask], criterion, base)
    right = _impurity(labels[~mask], None if child_w is None else child_w[~mask], criterion, base)
    total = w_left + w_right
    return float(w_left / total * left + w_right / total * right)


def information_gain(
    labels: np.ndarray,
    left_mask: np.ndarray,
    criterion: str = "entropy",
    weights: np.ndarray | None = None,
    base: float = 2.0,
) -> float:
    """Parent impurity minus mass-weighted child impurity."""
    children = weighted_child_impurity(labels, left_mask, criterion, weights, base)
    return float(_impurity(np.asarray(labels), weights, criterion, base) - children)

import numpy as np


def _validate(x: np.ndarray, y: np.ndarray, alpha: float) -> tuple[np.ndarray, np.ndarray]:
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if x.ndim != 2 or y.shape != (x.shape[0],):
        raise ValueError("expected x (n, d) and y (n,)")
    if alpha < 0:
        raise ValueError("alpha must be non-negative")
    return x, y


def ridge_loss(x: np.ndarray, y: np.ndarray, w: np.ndarray, b: float, alpha: float = 0.0) -> float:
    """mean squared error / 2 + alpha / 2 * ||w||^2 (intercept unpenalized)."""
    x, y = _validate(x, y, alpha)
    residual = x @ w + b - y
    return float(np.mean(residual ** 2) / 2 + 0.5 * alpha * w @ w)


def ridge_gradient(
    x: np.ndarray, y: np.ndarray, w: np.ndarray, b: float, alpha: float = 0.0
) -> tuple[np.ndarray, float]:
    """dJ/dw = X^T r / n + alpha w, dJ/db = mean(r)."""
    x, y = _validate(x, y, alpha)
    residual = x @ w + b - y
    return x.T @ residual / len(y) + alpha * w, float(residual.mean())


def fit_ridge_gd(
    x: np.ndarray, y: np.ndarray, alpha: float = 0.0, learning_rate: float = 0.1, steps: int = 1000
) -> tuple[np.ndarray, float, list[float]]:
    """Full-batch gradient descent from zeros."""
    x, y = _validate(x, y, alpha)
    w, b = np.zeros(x.shape[1]), 0.0
    history = []
    for _ in range(steps):
        grad_w, grad_b = ridge_gradient(x, y, w, b, alpha)
        w = w - learning_rate * grad_w
        b = b - learning_rate * grad_b
        history.append(ridge_loss(x, y, w, b, alpha))
    return w, b, history


def ridge_closed_form(x: np.ndarray, y: np.ndarray, alpha: float = 0.0) -> tuple[np.ndarray, float]:
    """Center to remove the intercept, then solve (never invert) the normal equations."""
    x, y = _validate(x, y, alpha)
    n, d = x.shape
    x_mean, y_mean = x.mean(axis=0), y.mean()
    xc, yc = x - x_mean, y - y_mean
    if alpha == 0:
        # lstsq works on Xc directly (SVD): min-norm for rank deficiency, and it avoids
        # squaring the condition number the way forming Xc^T Xc does.
        w = np.linalg.lstsq(xc, yc, rcond=None)[0]
    else:
        w = np.linalg.solve(xc.T @ xc / n + alpha * np.eye(d), xc.T @ yc / n)
    return w, float(y_mean - x_mean @ w)

import numpy as np


class KNearestNeighbors:
    """Exact kNN with stable tie handling and uniform or inverse-distance weights."""

    def __init__(self, k: int = 5, task: str = "classification", weights: str = "uniform") -> None:
        if k < 1:
            raise ValueError("k must be >= 1")
        if task not in ("classification", "regression"):
            raise ValueError("task must be 'classification' or 'regression'")
        if weights not in ("uniform", "distance"):
            raise ValueError("weights must be 'uniform' or 'distance'")
        self.k, self.task, self.weights = k, task, weights

    def fit(self, x: np.ndarray, y: np.ndarray) -> "KNearestNeighbors":
        x = np.array(x, dtype=float)  # copies: the model owns its training data
        y = np.array(y)
        if x.ndim != 2 or y.shape != (x.shape[0],):
            raise ValueError("expected x (n, d) and y (n,)")
        if self.k > len(x):
            raise ValueError("k cannot exceed the number of training rows")
        self.x_, self.y_ = x, y
        if self.task == "classification":
            self.classes_, self.codes_ = np.unique(y, return_inverse=True)  # sorted labels
        return self

    def kneighbors(self, x: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        x = np.asarray(x, dtype=float)
        if x.ndim != 2 or x.shape[1] != self.x_.shape[1]:
            raise ValueError("query feature dimension does not match training data")
        # Direct differences, O(q n d) memory: unlike the norm expansion, identical points
        # get exactly 0, which the zero-distance weighting rule depends on.
        dist = np.sqrt(((x[:, None, :] - self.x_[None, :, :]) ** 2).sum(axis=2))  # (q, n)
        idx = np.argsort(dist, axis=1, kind="stable")[:, :self.k]  # ties -> lower row index
        return np.take_along_axis(dist, idx, axis=1), idx

    def _neighbor_weights(self, dist: np.ndarray) -> np.ndarray:
        if self.weights == "uniform":
            return np.ones_like(dist)
        exact = dist == 0
        # Rows with an exact match use only those matches; others use 1 / d (d > 0 there).
        inverse = np.divide(1.0, dist, out=np.zeros_like(dist), where=~exact)
        return np.where(exact.any(axis=1, keepdims=True), exact.astype(float), inverse)

    def predict(self, x: np.ndarray) -> np.ndarray:
        dist, idx = self.kneighbors(x)
        w = self._neighbor_weights(dist)
        if self.task == "regression":
            return (w * self.y_[idx]).sum(axis=1) / w.sum(axis=1)
        votes = np.zeros((len(idx), len(self.classes_)))
        rows = np.repeat(np.arange(len(idx)), self.k)
        np.add.at(votes, (rows, self.codes_.ravel()[idx].ravel()), w.ravel())
        return self.classes_[np.argmax(votes, axis=1)]  # first max -> smallest label

import numpy as np


class MultinomialNaiveBayes:
    """Multinomial NB with Laplace smoothing; all scoring happens in log space."""

    def __init__(self, alpha: float = 1.0) -> None:
        if alpha <= 0:
            raise ValueError("alpha must be positive")
        self.alpha = alpha

    def fit(self, x: np.ndarray, y: np.ndarray) -> "MultinomialNaiveBayes":
        x = np.asarray(x, dtype=float)
        y = np.asarray(y)
        if x.ndim != 2 or y.shape != (x.shape[0],):
            raise ValueError("expected x (n, d) and y (n,)")
        if np.any(x < 0):
            raise ValueError("counts must be non-negative")
        self.classes_, codes = np.unique(y, return_inverse=True)
        codes = codes.ravel()
        n_classes, d = len(self.classes_), x.shape[1]
        one_hot = np.zeros((len(y), n_classes))
        one_hot[np.arange(len(y)), codes] = 1.0
        feature_counts = one_hot.T @ x  # (C, d): N_cj
        self.class_log_prior_ = np.log(one_hot.sum(axis=0) / len(y))  # documents per class
        smoothed = feature_counts + self.alpha
        self.feature_log_prob_ = np.log(smoothed) - np.log(smoothed.sum(axis=1, keepdims=True))
        return self

    def joint_log_likelihood(self, x: np.ndarray) -> np.ndarray:
        x = np.asarray(x, dtype=float)
        if x.ndim != 2 or x.shape[1] != self.feature_log_prob_.shape[1]:
            raise ValueError("feature count does not match the fitted model")
        return x @ self.feature_log_prob_.T + self.class_log_prior_

    def predict(self, x: np.ndarray) -> np.ndarray:
        return self.classes_[np.argmax(self.joint_log_likelihood(x), axis=1)]  # first max

    def predict_proba(self, x: np.ndarray) -> np.ndarray:
        jll = self.joint_log_likelihood(x)
        shifted = jll - jll.max(axis=1, keepdims=True)  # log-sum-exp shift
        log_norm = np.log(np.exp(shifted).sum(axis=1, keepdims=True))
        return np.exp(shifted - log_norm)

import numpy as np


def pad_sequences(sequences: list[np.ndarray]) -> tuple[np.ndarray, np.ndarray]:
    """Right-pad `(L_i, d)` sequences into `(B, T, d)` with a `(B, T)` boolean mask."""
    if not sequences:
        raise ValueError("need at least one sequence")
    arrays = [np.asarray(s, dtype=float) for s in sequences]
    if any(a.ndim != 2 for a in arrays) or len({a.shape[1] for a in arrays}) != 1:
        raise ValueError("every sequence must be 2-D with the same d")
    lengths = np.array([len(a) for a in arrays], dtype=np.intp)
    b, t, d = len(arrays), int(lengths.max()), arrays[0].shape[1]

    mask = np.arange(t)[None, :] < lengths[:, None]  # (B, T)
    padded = np.zeros((b, t, d))
    # Row-major order of mask's True cells matches the concatenated sequences.
    padded[mask] = np.concatenate(arrays, axis=0)
    return padded, mask


def masked_mean_pool(padded: np.ndarray, mask: np.ndarray) -> np.ndarray:
    """Mean over real positions; rows with no real positions give zeros."""
    weights = mask.astype(float)[..., None]  # (B, T, 1) broadcasts over d
    counts = weights.sum(axis=1)  # (B, 1)
    # where() rather than padded * weights: garbage such as inf/NaN in padding stays out.
    sums = np.where(weights > 0, padded, 0.0).sum(axis=1)
    return sums / np.maximum(counts, 1.0)


def last_n_mean_pool(padded: np.ndarray, mask: np.ndarray, n: int = 5) -> np.ndarray:
    """Mean over the last `n` real positions (by time index), for any mask pattern."""
    if n < 1:
        raise ValueError("n must be >= 1")
    # rank_from_end[b, t] = number of real positions at index >= t (1 for the last one).
    rank_from_end = np.cumsum(mask[:, ::-1], axis=1)[:, ::-1]
    return masked_mean_pool(padded, mask & (rank_from_end <= n))


def masked_max_pool(padded: np.ndarray, mask: np.ndarray) -> np.ndarray:
    """Max over real positions; padding is replaced by -inf so it can never win."""
    masked = np.where(mask[..., None], padded, -np.inf)
    out = masked.max(axis=1, initial=-np.inf)  # initial handles T == 0
    return np.where(mask.any(axis=1)[:, None], out, 0.0)


def pad_and_pool(
    sequences: list[np.ndarray],
) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    """Pad, then return the masked mean and the mean of the last five real positions."""
    padded, mask = pad_sequences(sequences)
    return padded, mask, masked_mean_pool(padded, mask), last_n_mean_pool(padded, mask, 5)

import numpy as np
import pandas as pd


def point_in_time_features(labels: pd.DataFrame, events: pd.DataFrame) -> pd.DataFrame:
    """Strictly-prior 1/7/30-day features per label row; see the PD-03 starter for the contract."""
    ordered = events.sort_values(["user_id", "event_ts"], kind="stable")
    by_user = {
        user: (
            group["event_ts"].to_numpy(),
            np.concatenate([[0.0], np.cumsum(group["amount"].fillna(0.0).to_numpy())]),
            group["event_type"].to_numpy(),
        )
        for user, group in ordered.groupby("user_id", sort=False)
    }
    windows = {"count_1d": 1, "count_7d": 7, "count_30d": 30}
    features = {name: np.zeros(len(labels), dtype=np.int64) for name in windows}
    amount_30d = np.zeros(len(labels))
    days_since_prev = np.full(len(labels), np.nan)
    distinct_types = np.zeros(len(labels), dtype=np.int64)

    for row, (user, label_ts) in enumerate(zip(labels["user_id"], labels["label_ts"])):
        if user not in by_user:
            continue
        times, amount_prefix, types = by_user[user]
        # side="left" counts events strictly before a bound: the end bound excludes
        # event_ts == label_ts, the start bound keeps event_ts == label_ts - N days.
        end = np.searchsorted(times, np.datetime64(label_ts), side="left")
        for name, days in windows.items():
            start = np.searchsorted(times, np.datetime64(label_ts - pd.Timedelta(days=days)), side="left")
            features[name][row] = end - start
            if days == 30:
                amount_30d[row] = amount_prefix[end] - amount_prefix[start]
                distinct_types[row] = len(set(types[start:end]))
        if end > 0:
            days_since_prev[row] = (label_ts - pd.Timestamp(times[end - 1])) / pd.Timedelta(days=1)

    return labels.assign(
        **features,
        amount_30d=amount_30d,
        days_since_prev_event=days_since_prev,
        distinct_event_types_30d=distinct_types,
    )

