def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _parse(line: str) -> dict[str, Any] | None:
    """Return a validated event dict, or None if the line is malformed."""
    try:
        event = json.loads(line)
    except json.JSONDecodeError:
        return None
    if not isinstance(event, dict):
        return None
    user_id, kind, ts = event.get("user_id"), event.get("event"), event.get("ts")
    if not (isinstance(user_id, int) and not isinstance(user_id, bool)):
        return None
    if not isinstance(kind, str) or not _is_number(ts):
        return None
    if kind in ("click", "purchase") and not isinstance(event.get("item_id"), (int, str)):
        return None
    if kind == "purchase" and not (_is_number(event.get("amount")) and event["amount"] >= 0):
        return None
    return event


def iter_events(json_lines: Iterable[str], malformed: Counter) -> Iterator[dict[str, Any]]:
    """Lazily yield valid events; count malformed lines in `malformed["count"]`."""
    for line in json_lines:
        if not line.strip():
            continue
        event = _parse(line)
        if event is None:
            malformed["count"] += 1
        else:
            yield event


def process_events(
    json_lines: Iterable[str],
    category_csv: str,
    session_gap: float = 1800,
    top_k: int = 3,
) -> dict[str, Any]:
    """Summarize events: sessions, top clicked categories, highest spender, malformed count."""
    category_of = {row["item_id"]: row["category"] for row in csv.DictReader(io.StringIO(category_csv))}

    malformed: Counter = Counter()
    clicks: Counter = Counter()
    spend: defaultdict[int, float] = defaultdict(float)
    times: defaultdict[int, list[float]] = defaultdict(list)
    # Counts and totals stream; sessions need each user's timestamps buffered and sorted.
    for event in iter_events(json_lines, malformed):
        user = event["user_id"]
        times[user].append(event["ts"])
        if event["event"] == "click":
            clicks[category_of.get(str(event["item_id"]), "unknown")] += 1
        elif event["event"] == "purchase":
            spend[user] += event["amount"]

    sessions: dict[int, list[tuple[float, float, int]]] = {}
    for user, stamps in times.items():
        stamps.sort()
        user_sessions = []
        start = previous = stamps[0]
        count = 0
        for ts in stamps:
            if ts - previous > session_gap:
                user_sessions.append((start, previous, count))
                start, count = ts, 0
            previous = ts
            count += 1
        user_sessions.append((start, previous, count))
        sessions[user] = user_sessions

    top = sorted(clicks.items(), key=lambda kv: (-kv[1], kv[0]))[:top_k]
    spender = min(spend, key=lambda u: (-spend[u], u)) if spend else None
    return {
        "sessions": sessions,
        "top_categories": top,
        "highest_spender": spender,
        "malformed_count": malformed["count"],
    }

import math
from typing import Any, Mapping, Sequence

UNKNOWN = "__unknown__"


def _is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, float) and math.isnan(value))


def _numeric(column: str, value: Any) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"column {column!r} expects a number, got {value!r}")
    return float(value)


class FeatureTransformer:
    """Standardize/impute/flag numeric columns and one-hot encode categorical columns."""

    def __init__(self, numeric: Sequence[str] = (), categorical: Sequence[str] = ()) -> None:
        self.numeric = list(numeric)
        self.categorical = list(categorical)
        self._fitted = False

    def fit(self, rows: Sequence[Mapping[str, Any]]) -> "FeatureTransformer":
        if not rows:
            raise ValueError("fit requires at least one row")
        # Build all new state locally, then swap it in, so a failed fit keeps no partial state.
        stats: dict[str, tuple[float, float]] = {}
        for column in self.numeric:
            values = [_numeric(column, row.get(column)) for row in rows if not _is_missing(row.get(column))]
            mean = sum(values) / len(values) if values else 0.0
            std = math.sqrt(sum((v - mean) ** 2 for v in values) / len(values)) if values else 0.0
            stats[column] = (mean, std if std > 0 else 1.0)
        categories = {
            column: sorted({row.get(column) for row in rows if not _is_missing(row.get(column))})
            for column in self.categorical
        }
        names = [name for column in self.numeric for name in (column, f"{column}__missing")]
        for column in self.categorical:
            names += [f"{column}={value}" for value in categories[column]] + [f"{column}={UNKNOWN}"]

        self.stats_, self.categories_, self.feature_names_ = stats, categories, names
        self._index = {column: {v: i for i, v in enumerate(categories[column])} for column in self.categorical}
        self._fitted = True
        return self

    def transform(self, rows: Sequence[Mapping[str, Any]]) -> list[list[float]]:
        if not self._fitted:
            raise RuntimeError("FeatureTransformer must be fit before transform")
        out = []
        for row in rows:
            features: list[float] = []
            for column in self.numeric:
                mean, scale = self.stats_[column]
                value = row.get(column)
                if _is_missing(value):
                    features += [0.0, 1.0]
                else:
                    features += [(_numeric(column, value) - mean) / scale, 0.0]
            for column in self.categorical:
                index = self._index[column]
                one_hot = [0.0] * (len(index) + 1)
                value = row.get(column)
                position = index.get(value, len(index)) if not _is_missing(value) else len(index)
                one_hot[position] = 1.0
                features += one_hot
            out.append(features)
        return out

    def fit_transform(self, rows: Sequence[Mapping[str, Any]]) -> list[list[float]]:
        return self.fit(rows).transform(rows)

"""Lazy record utilities: parse, transform, batch, and aggregate streams."""
import json
from typing import Any, Callable, Iterable, Iterator, TypeVar

T = TypeVar("T")
U = TypeVar("U")


class RecordError(Exception):
    """A record could not be read or transformed at `position`."""

    def __init__(self, message: str, position: int) -> None:
        super().__init__(message)
        self.position = position


def parse_jsonl(lines: Iterable[str]) -> Iterator[dict[str, Any]]:
    """Lazily parse JSON-object lines, skipping blank lines."""
    for line_number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError as exc:
            raise RecordError(f"line {line_number}: invalid JSON: {exc.msg}", line_number) from exc
        if not isinstance(record, dict):
            cause = TypeError(f"expected a JSON object, got {type(record).__name__}")
            raise RecordError(f"line {line_number}: {cause}", line_number) from cause
        yield record


def transform_records(records: Iterable[T], fn: Callable[[T], U]) -> Iterator[U]:
    """Lazily apply fn, wrapping failures with the record index."""
    for index, record in enumerate(records):
        try:
            result = fn(record)
        except Exception as exc:
            raise RecordError(f"record {index}: {type(exc).__name__}: {exc}", index) from exc
        yield result


def batched(records: Iterable[T], batch_size: int) -> Iterator[list[T]]:
    """Group records into lists of batch_size; validates eagerly, iterates lazily."""
    # Validation lives outside the generator so a bad size fails at call time.
    if batch_size < 1:
        raise ValueError("batch_size must be >= 1")
    return _batches(iter(records), batch_size)


def _batches(iterator: Iterator[T], batch_size: int) -> Iterator[list[T]]:
    batch: list[T] = []
    for record in iterator:
        batch.append(record)
        if len(batch) == batch_size:
            yield batch
            batch = []
    if batch:
        yield batch


class StreamingStats:
    """Welford running statistics with O(1) state."""

    def __init__(self) -> None:
        self._count = 0
        self._mean = 0.0
        self._m2 = 0.0  # sum of squared deviations from the running mean
        self._min: float | None = None
        self._max: float | None = None

    def update(self, value: float) -> None:
        self._count += 1
        delta = value - self._mean
        self._mean += delta / self._count
        self._m2 += delta * (value - self._mean)
        self._min = value if self._min is None else min(self._min, value)
        self._max = value if self._max is None else max(self._max, value)

    @property
    def count(self) -> int:
        return self._count

    @property
    def mean(self) -> float | None:
        return self._mean if self._count else None

    @property
    def variance(self) -> float | None:
        return self._m2 / self._count if self._count else None

    @property
    def minimum(self) -> float | None:
        return self._min

    @property
    def maximum(self) -> float | None:
        return self._max

