def _brute(intervals):
    points = sorted({x for s, e in intervals for x in range(2 * s, 2 * e + 1)})
    merged = []
    for p in points:
        if merged and p == merged[-1][1] + 1:
            merged[-1][1] = p
        else:
            merged.append([p, p])
    return [[s // 2, e // 2] for s, e in merged]


